_elementor_page_settings.custom_css:
/* boxed gradient hero — matches site service pages (water-process) */
.wp-hero{background:#f6f9ff;padding:clamp(2rem,1.5rem+2vw,3.5rem) clamp(1.25rem,.5rem+3vw,3rem);}
.wp-hero-box{max-width:1728px;margin:0 auto;background:linear-gradient(90deg,#005287 0%,#72cac4 100%);border-radius:12px;padding:clamp(4.5rem,3.5rem+4vw,7rem) clamp(1.5rem,1rem+3vw,4rem);position:relative;overflow:hidden;}
.wp-hero-inner{max-width:900px;margin:0 auto;text-align:center;display:flex;flex-direction:column;align-items:center;gap:18px;position:relative;z-index:1;}
.wp-badge{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.18);color:#fff;font-size:12px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;padding:8px 16px;border-radius:8px;}
.wp-badge i{width:8px;height:8px;border-radius:50%;background:#bdeee9;display:inline-block;}
.wp-hero-inner h1{color:#fff;font-size:clamp(2rem,1.4rem+2.1vw,2.85rem);font-weight:800;line-height:1.18;letter-spacing:-.01em;margin:0;}
.wp-sub{color:rgba(255,255,255,.92);font-size:clamp(1rem,.95rem+.35vw,1.18rem);line-height:1.55;margin:0;max-width:66ch;}
.wp-cta{display:inline-block;background:#e4f1f9;color:#005287;font-weight:700;font-size:1rem;padding:13px 28px;border-radius:8px;text-decoration:none;margin-top:8px;}
.wp-cta:hover{background:#fff;}

.pg-body{max-width:1180px;margin:0 auto;padding:clamp(3rem,2rem+3vw,5rem) clamp(1.25rem,.5rem+3vw,3rem) 6rem;font-family:'Inter',sans-serif;color:#242d28;}
.pg-body a{color:#3765f8;text-decoration:none;}.pg-body a:hover{text-decoration:underline;}

.job-form{max-width:820px;margin:0 auto;}
.job-intro p{color:#5d665f;font-size:1.05rem;line-height:1.6;margin:0 0 2rem;text-align:center;}
.job-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;}
.job-grid label{display:flex;flex-direction:column;gap:7px;font-weight:600;color:#1b216b;font-size:.9rem;}
.job-grid label.full{grid-column:1 / -1;}
.job-grid label span{color:#f47b2e;margin-left:2px;}
.job-grid input,.job-grid textarea{font-family:'Inter',sans-serif;font-size:1rem;color:#242d28;border:1px solid #c9d2d8;border-radius:8px;padding:11px 14px;background:#fff;}
.job-grid input:focus,.job-grid textarea:focus{outline:none;border-color:#3765f8;box-shadow:0 0 0 3px rgba(55,101,248,.15);}
.job-grid input[type=file]{padding:9px;background:#f5f7f9;}
.job-submit{margin-top:1.75rem;background:#3765f8;color:#fff;border:0;border-radius:8px;font-family:'Inter',sans-serif;font-weight:700;font-size:1rem;padding:14px 32px;cursor:pointer;}
.job-submit:hover{background:#1b216b;}
.job-note{color:#8b938c;font-size:.8rem;margin-top:1rem;}
@media(max-width:680px){.job-grid{grid-template-columns:1fr;}}
